function mkText(chars, o={}){
  const t = figma.createText();
  t.fontName = {family:o.family||'Nunito', style:o.style||'Regular'};
  t.characters = chars;
  t.fontSize = o.size||14;
  t.fills = solid(o.color||'241F2A');
  if(o.lh) t.lineHeight = {value:o.lh, unit:'PIXELS'};
  if(o.width){ t.textAutoResize='HEIGHT'; t.resize(o.width, t.height); }
  if(o.align) t.textAlignHorizontal=o.align;
  if(o.name) t.name=o.name;
  if(o.ls) t.letterSpacing={value:o.ls,unit:'PIXELS'};
  return t;
}
function mkFrame(name, o={}){
  const f = figma.createFrame(); f.name=name;
  f.fills = o.fill? solid(o.fill):[];
  if(o.w&&o.h) f.resize(o.w,o.h);
  if(o.layout){ f.layoutMode=o.layout; f.primaryAxisSizingMode=o.pSize||'AUTO'; f.counterAxisSizingMode=o.cSize||'AUTO';
    f.itemSpacing=o.gap||0; f.paddingLeft=o.pl||0; f.paddingRight=o.pr||0; f.paddingTop=o.pt||0; f.paddingBottom=o.pb||0;
    f.primaryAxisAlignItems=o.main||'MIN'; f.counterAxisAlignItems=o.cross||'CENTER'; }
  if(o.radius!==undefined) f.cornerRadius=o.radius;
  if(o.stroke){ f.strokes=solid(o.stroke); f.strokeWeight=o.sw||1; }
  f.clipsContent = o.clips===undefined? false : o.clips;
  return f;
}
async function mkIcon(compId, size, color){
  const src = await figma.getNodeByIdAsync(compId);
  const inst = src.createInstance();
  const ow = inst.width;
  inst.resize(size,size);
  const k = size/ow;
  const walk = n => {
    if(n.type==='VECTOR'||n.type==='BOOLEAN_OPERATION'||n.type==='STAR'||n.type==='POLYGON'||n.type==='ELLIPSE'||n.type==='RECTANGLE'||n.type==='LINE'){
      if(n.strokes && n.strokes.length && n.strokes[0].visible!==false){ n.strokes = solid(color); n.strokeWeight = Math.max(1,(n.strokeWeight||2)*k); }
      else if(n.fills && n.fills.length && n.fills[0].type==='SOLID'){ n.fills = solid(color); }
    }
    if('children' in n) n.children.forEach(walk);
  };
  walk(inst);
  inst.name = src.name;
  return inst;
}

