function register(name, comp, parent){
  const wrap = mkFrame('C·'+name, {layout:'VERTICAL', gap:8, cross:'MIN'});
  wrap.appendChild(mkText(name, {family:'Nunito', style:'Bold', size:12, color:'6F667A'}));
