function mkText(chars,o={}){const t=figma.createText();t.fontName={family:o.family||'Nunito',style:o.style||'Regular'};t.characters=chars;t.fontSize=o.size||14;t.fills=solid(o.color||'241F2A');if(o.lh)t.lineHeight={value:o.lh,unit:'PIXELS'};if(o.width){t.textAutoResize='HEIGHT';t.resize(o.width,t.height);}if(o.align)t.textAlignHorizontal=o.align;if(o.name)t.name=o.name;if(o.lines){t.textTruncation='ENDING';t.maxLines=o.lines;}return t;}
function mkFrame(name,o={}){const f=figma.createFrame();f.name=name;f.fills=o.fill?solid(o.fill):[];if(o.w&&o.h)f.resize(o.w,o.h);if(o.layout){f.layoutMode=o.layout;f.primaryAxisSizingMode=o.pSize||'AUTO';f.counterAxisSizingMode=o.cSize||'AUTO';f.itemSpacing=o.gap||0;f.paddingLeft=o.pl||0;f.paddingRight=o.pr||0;f.paddingTop=o.pt||0;f.paddingBottom=o.pb||0;f.primaryAxisAlignItems=o.main||'MIN';f.counterAxisAlignItems=o.cross||'CENTER';}if(o.radius!==undefined)f.cornerRadius=o.radius;if(o.stroke){f.strokes=solid(o.stroke);f.strokeWeight=o.sw||1;}f.clipsContent=o.clips===undefined?false:o.clips;return f;}
function recolor(node,color){const walk=n=>{if(n.type==='VECTOR'||n.type==='BOOLEAN_OPERATION'||n.type==='ELLIPSE'||n.type==='RECTANGLE'||n.type==='LINE'||n.type==='STAR'||n.type==='POLYGON'){if(n.strokes&&n.strokes.length&&n.strokes[0].visible!==false)n.strokes=solid(color);else if(n.fills&&n.fills.length&&n.fills[0].type==='SOLID')n.fills=solid(color);}if('children' in n)n.children.forEach(walk);};walk(node);}
async function mkIcon(compId,size,color){const src=await figma.getNodeByIdAsync(compId);const i=src.createInstance();const k=size/i.width;i.resize(size,size);const walk=n=>{if(n.type==='VECTOR'||n.type==='BOOLEAN_OPERATION'||n.type==='ELLIPSE'||n.type==='RECTANGLE'||n.type==='LINE'){if(n.strokes&&n.strokes.length&&n.strokes[0].visible!==false)n.strokeWeight=Math.max(1,(n.strokeWeight||2)*k);}if('children' in n)n.children.forEach(walk);};walk(i);recolor(i,color);i.name=src.name;return i;}
async function inst(id){return (await figma.getNodeByIdAsync(id)).createInstance();}
function screen(name,x,y){const f=figma.createFrame();f.name=name;f.resize(428,928);f.x=x;f.y=y;f.fills=solid('F7F4FA');f.clipsContent=true;ws.appendChild(f);return f;}
async function shell(f){const sb=await inst('3:34');sb.x=0;sb.y=0;f.appendChild(sb);const hi=await inst('3:45');hi.x=0;hi.y=894;f.appendChild(hi);}
async function coverInst(srcId,w,h){const im=await inst(srcId);const k=Math.max(w/im.width,h/im.height);im.resize(im.width*k,im.height*k);im.x=(w-im.width)/2;im.y=(h-im.height)/2;return im;}
async function navBar(f,title){const nb=await inst('50:101');nb.x=0;nb.y=47;f.appendChild(nb);nb.findOne(n=>n.name==='title').characters=title;return nb;}
async function footer(f,y){const ft=mkFrame('footer',{layout:'VERTICAL',gap:8,cross:'CENTER',w:380});ft.x=24;ft.y=y;f.appendChild(ft);
