  const f=figma.createFrame();f.layoutMode='VERTICAL';f.itemSpacing=gap||0;
  f.paddingLeft=f.paddingRight=f.paddingTop=f.paddingBottom=pad||0;
  f.cornerRadius=radius||0;f.fills=[{type:'SOLID',color:C.white}];
  f.resize(w,10);f.layoutSizingHorizontal='FIXED';f.layoutSizingVertical='HUG';
  return f;
}

