/* ===== helper: settings row instance ===== */
const settingsRow=await figma.getNodeByIdAsync('50:140');
async function sRow(iconId,label,value,valueColor){
  const i=settingsRow.createInstance();
  const ic=i.children[0].children[0];
  const m=await media(iconId);
  if(m&&ic.swapComponent)ic.swapComponent(m);
  recolor(ic,C.sec);
  i.findOne(n=>n.name==='label').characters=label;
  const v=i.findOne(n=>n.name==='value');
  if(value){v.characters=value;v.fills=[{type:'SOLID',color:valueColor||C.sec}];}
  else v.visible=false;
  return i;
}
