const mediaCache={};
async function media(id){
  if(mediaCache[id])return mediaCache[id];
  const n=await figma.getNodeByIdAsync(id);
  const c = n.type==='COMPONENT'? n : (n.type==='INSTANCE'? n.mainComponent : null);
  mediaCache[id]=c; return c;
}
async function inst(id,size){
  const m=await media(id);
  let i;
  if(m){i=m.createInstance();} else {i=(await figma.getNodeByIdAsync(id)).clone();}
  if(size)i.resize(size,size);
  return i;
}
function recolor(node,color){
  const vs=node.findAll?node.findAll(n=>n.type==='VECTOR'):(node.type==='VECTOR'?[node]:[]);
  for(const v of vs){ if(v.fills&&v.fills.length&&v.fills[0].type==='SOLID') v.fills=[{type:'SOLID',color}]; if(v.strokes&&v.strokes.length&&v.strokes[0].type==='SOLID') v.strokes=[{type:'SOLID',color}]; }
}
function T(chars,font,size,color,opts){
  const t=figma.createText();t.fontName=font;t.fontSize=size;t.characters=chars;
  t.fills=[{type:'SOLID',color}];
  if(opts){if(opts.lh)t.lineHeight={value:opts.lh,unit:'PIXELS'};if(opts.name)t.name=opts.name;if(opts.align)t.textAlignHorizontal=opts.align;}
  return t;
}
