const out=[];
// Replace Status Bar / Home Indicator strays with instances of originals
const sbMain = await figma.getNodeByIdAsync('3:34');
const hiMain = await figma.getNodeByIdAsync('3:45');
const pairs=[['70:564','sb'],['70:575','hi'],['70:668','sb'],['70:679','hi'],['70:737','sb'],['70:748','hi'],['72:743','sb'],['72:910','hi']];
for(const [id,kind] of pairs){
  const n=await figma.getNodeByIdAsync(id);
  const parent=n.parent;
  const idx=parent.children.indexOf(n);
  const inst=(kind==='sb'?sbMain:hiMain).createInstance();
  parent.insertChild(idx,inst);
  if(kind==='hi'){inst.layoutPositioning='ABSOLUTE';inst.x=0;inst.y=928-34;}
  n.remove();
  out.push(kind+' replaced in '+parent.name);
}
