const ws = figma.root.children.find(p=>p.name.includes('Workspace'));
await figma.setCurrentPageAsync(ws);
const frames = ws.children.filter(n=>n.type==='FRAME');
const issues=[];
for(const f of frames){
  if(f.name.startsWith('Design')) continue;
  const stray = f.findAll(n=>n.type==='COMPONENT');
  if(stray.length) issues.push({frame:f.name,stray:stray.map(s=>s.name+':'+s.id)});
  for(const c of f.children){
    if(c.layoutPositioning==='ABSOLUTE') continue;
    if(c.y+c.height > f.height+1) issues.push({frame:f.name,overflow:c.name+' bottom='+Math.round(c.y+c.height)});
  }
}
return JSON.stringify(issues);

